class IndependentSpyAndAaplStrategies(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}

        for ticker in self.tickers:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.closes = {ticker: deque(maxlen=101) for ticker in self.tickers}
        self.previous_sma100 = None
        self.previous_spy_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        bars = {}

        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                return
            bars[ticker] = data.Bars[symbol]

        for ticker in self.tickers:
            close = float(bars[ticker].Close)
            prior_close = self.closes[ticker][-1] if self.closes[ticker] else None

            if ticker == "AAPL":
                if prior_close is not None and close < prior_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.closes[ticker].append(close)

        if len(self.closes["SPY"]) < 101 or len(self.closes["AAPL"]) < 15:
            return

        spy_close = float(bars["SPY"].Close)
        spy_sma100 = sum(list(self.closes["SPY"])[-100:]) / 100.0
        aapl_rsi14 = self.CalculateRsi14(list(self.closes["AAPL"])[-15:])

        if self.IsWarmingUp:
            self.previous_spy_close = spy_close
            self.previous_sma100 = spy_sma100
            return

        if self.previous_spy_close is None or self.previous_sma100 is None:
            self.previous_spy_close = spy_close
            self.previous_sma100 = spy_sma100
            return

        spy_crosses_below = (
            self.previous_spy_close >= self.previous_sma100 and
            spy_close < spy_sma100
        )
        spy_crosses_above = (
            self.previous_spy_close <= self.previous_sma100 and
            spy_close > spy_sma100
        )

        # Sells before buys.
        if self.strategy_a_shares > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and aapl_rsi14 > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crosses_above:
            target_value = float(self.Portfolio.TotalPortfolioValue) * 0.40
            shares = int(floor(target_value / spy_close))
            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            aapl_close = float(bars["AAPL"].Close)
            if float(self.Portfolio.Cash) >= 20000:
                shares = int(floor(20000 / aapl_close))
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares

        self.previous_spy_close = spy_close
        self.previous_sma100 = spy_sma100

    def CalculateRsi14(self, closes):
        gains = 0.0
        losses = 0.0

        for i in range(1, 15):
            change = closes[i] - closes[i - 1]
            if change > 0:
                gains += change
            elif change < 0:
                losses -= change

        average_gain = gains / 14.0
        average_loss = losses / 14.0

        if average_loss == 0:
            return 100.0

        rs = average_gain / average_loss
        return 100.0 - (100.0 / (1.0 + rs))
